<?php // $p is a product selected by a prepared query. ?>
<article class="product-card reveal"><div class="product-image"><a href="<?= url('product.php?id='.$p['id']) ?>"><img src="<?= image_url($p['image']) ?>" alt="<?= e($p['name']) ?>" loading="lazy" width="500" height="420"></a><?php if($p['sale_price']!==null): ?><span class="sale-badge">−<?= (int)round((1-price($p)/(float)$p['price'])*100) ?>%</span><?php endif; ?><form action="<?= url('action.php') ?>" method="post" data-ajax><?= csrf() ?><input type="hidden" name="action" value="wishlist"><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="wish-btn" aria-label="Toggle <?= e($p['name']) ?> in wishlist"><i class="fa-regular fa-heart" aria-hidden="true"></i></button></form><button class="quick-btn" data-quick="<?= $p['id'] ?>">Quick view <i class="fa-solid fa-expand" aria-hidden="true"></i></button></div><div class="product-info"><div class="product-meta"><span><?= e($p['category_name'] ?? 'Collection') ?></span><span class="stars">★ <?= (float)$p['rating']>0?number_format((float)$p['rating'],1):'New' ?></span></div><h3><a href="<?= url('product.php?id='.$p['id']) ?>"><?= e($p['name']) ?></a></h3><div class="price-line"><strong><?= money(price($p)) ?></strong><?php if($p['sale_price']!==null): ?><del><?= money($p['price']) ?></del><?php endif; ?><small class="stock <?= $p['stock']?'':'out' ?>"><?= $p['stock']?'In stock':'Sold out' ?></small></div><form action="<?= url('action.php') ?>" method="post" class="card-actions" data-ajax><?= csrf() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><input type="hidden" name="size" value="<?= e(options($p['sizes'])[0] ?? '') ?>"><input type="hidden" name="color" value="<?= e(options($p['colors'])[0] ?? '') ?>"><input type="hidden" name="quantity" value="1"><button class="btn btn-soft" name="action" value="add" <?= !$p['stock']?'disabled':'' ?>><i class="fa-solid fa-plus" aria-hidden="true"></i> Add to cart</button><button class="btn btn-accent" name="action" value="buy" <?= !$p['stock']?'disabled':'' ?>>Buy now ↗</button></form></div></article>
